require __DIR__.'/common.php';$s=json_decode(file_get_contents(__DIR__.'/scope.json'),true,512,JSON_THROW_ON_ERROR);$rows=[];foreach($s['target_ids'] as $id){$p=get_post($id);if(!$p||$p->post_type!=='product'||$p->post_status!=='publish'||!has_term(212,'product_cat',$id))throw new RuntimeException('Scope drift');$rows[]=['id'=>$id,'url'=>get_permalink($id),'slug'=>$p->post_name,'content'=>$p->post_content,'excerpt'=>$p->post_excerpt,'invariant'=>invariant($id),'before'=>values($id),'counts'=>counts($id),'indexables'=>indexable($id)];}$prior=[];foreach($s['preserve_ids'] as $id)$prior[$id]=invariant($id,false);echo json_encode(['utc'=>gmdate('c'),'products'=>$rows,'prior'=>$prior],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);
